import type { BookChapter } from "../types";

/* The Discover book — topic 1.5 (Feasibility & the Technical Decision), and the closing */
export const chapter5: BookChapter = {
  id: "day-5", n: "5", day: 5, title: "Feasibility & the Technical Decision", kicker: "Technical Discovery Decision",
  question: "Which approach do we commit to — and what does it cost?",
  intro: [
    { t: "p", text: "Everything you’ve done in the previous topics has led here. In this topic you rate whether each option can really be built and run here, put honest ranges on its effort, cost and risk, compare the options side by side and recommend one — then record the decision so PLAN starts from evidence, not from a conversation nobody wrote down." },
    { t: "p", text: "Topic 1.4 left you with real choices: options found in the market, scored fairly against your quality targets, the riskiest part proven by a spike, and two or three architecture options drawn box by box. What you don’t yet have is a *decision*. A list of good options is not a plan; it is a menu. This topic turns the menu into one explicit choice, with its price and its risks written next to it, and a record that anyone can follow months from now." },
    { t: "p", text: "The four lessons are a chain. Each one consumes what the one before it produced, and each ends with a person — usually the tech lead — saying yes, no, or not yet. You can’t estimate an option you haven’t shown to be feasible; you can’t compare options you haven’t estimated; and you can’t record a decision nobody has accepted." },
    { t: "figure", fig: { kind: "flow", steps: [ { label: "1.5.1 Assess feasibility", sub: "gate: Feasibility Rated" }, { label: "1.5.2 Estimate effort, risk & cost", sub: "gate: Estimates Reviewed" }, { label: "1.5.3 Compare & recommend", sub: "gate: Recommendation Accepted" }, { label: "1.5.4 Record the decision (ADR)", sub: "gate: Technical Discovery Decision" } ] }, caption: "The four lessons as a chain: each consumes what the one before produced, and each ends with a gate where a person says yes, no or not yet." },
    { t: "table", caption: "Topic 1.5 at a glance", head: ["Lesson", "The question", "What it produces", "Its gate", "Timebox"], rows: [
      ["1.5.1 Assess Technical Feasibility", "Can we build and run it *here*?", "Feasibility assessment — rating, evidence, unknowns, skills, conditions", "Feasibility Rated", "2–4 hours"],
      ["1.5.2 Estimate Effort, Risk & Cost", "How big is it, and what could go wrong?", "Effort estimate as ranges, and a risk register", "Estimates Reviewed", "½ day"],
      ["1.5.3 Compare Options & Recommend", "Which one, and what do we give up?", "Option comparison & recommendation", "Recommendation Accepted", "2–4 hours"],
      ["1.5.4 Record the Decision (ADR)", "What did we decide, and why?", "ADR, technical discovery handoff pack, learning log", "Technical Discovery Decision", "2–4 hours"],
    ] },
    { t: "p", text: "The act closes at the **Technical Discovery Decision**: feasibility evidenced, estimates as ranges, every risk owned, trade-offs stated, and the ADR complete. Pass it, and the ADR and its handoff pack go to PLAN, which opens Act II; what discovery taught you goes to the learning log, for EVOLVE." },
    { t: "figure", fig: { kind: "tree", root: "Technical Discovery Decision", children: [ { label: "To PLAN (Act II)", text: "PLAN starts from evidence, not from a conversation.", children: [ { label: "ADR" }, { label: "Handoff pack" } ] }, { label: "To the learning log", text: "What discovery taught you, for EVOLVE." } ] }, caption: "What passing the act’s gate sends on: the ADR and its handoff pack open PLAN; what discovery taught you goes to the learning log." },
    { t: "callout", tone: "key", title: "The gate for Act I", text: "Five things must be true: **feasibility evidenced** (every rating cites a spike or a document), **estimates as ranges** (never single numbers), **risks owned** (every risk has a named person), **trade-offs stated** (what the choice gives up, in plain words), and the **ADR complete** (context, decision, options considered, consequences, dated conditions, linked evidence)." },
    { t: "figure", fig: { kind: "hub", center: "The gate for Act I", items: [ { label: "Feasibility evidenced", icon: "fact_check", text: "Every rating cites a spike or a document." }, { label: "Estimates as ranges", icon: "query_stats", text: "Never single numbers." }, { label: "Risks owned", icon: "person", text: "Every risk has a named person." }, { label: "Trade-offs stated", icon: "balance", text: "What the choice gives up, in plain words." }, { label: "ADR complete", icon: "gavel", text: "Context, decision, options considered, consequences, dated conditions, linked evidence." } ] }, caption: "The five things that must be true to pass the Technical Discovery Decision. Miss any one and the act does not close." },
  ],
  sections: [
    /* ───────────────────────────── 1.5.1 ───────────────────────────── */
    {
      id: "discover.decide.feasibility", fid: "discover.decide.feasibility", code: "1.5.1", title: "Assess Technical Feasibility", minutes: 11,
      blocks: [
        { t: "lead", text: "“Can we build it?” is two questions: can it be built at all, and can it be built and run *here* — with these people, these systems, these rules. This lesson rates each option’s feasibility from the evidence you’ve gathered, and writes down the conditions it depends on." },
        { t: "tldr", items: [
          "Rate every option high, medium or low — and cite the spike result or document behind each rating.",
          "An unknown is never rated as low risk; if it hasn’t been spiked, it is a risk with a way to resolve it.",
          "Write the conditions each rating depends on as specific, checkable, dated facts.",
          "Missing skills don’t sink an option — rate it with the training or hire it needs.",
          "The tech lead signs off the ratings; conditions outside the team’s control go to the tech lead and the client.",
        ] },
        { t: "p", text: "The job: *help me know which options we can really build and run, and what must be true for that.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Most failed projects were not impossible. They were feasible *somewhere* — with a different team, a different contract, a different vendor answer — and nobody checked whether they were feasible in the place they were actually going to be built. A feasibility assessment is the moment you check." },
        { t: "figure", fig: { kind: "split", left: { title: "Feasible somewhere", items: ["A different team", "A different contract", "A different vendor answer"], tone: "bad" }, right: { title: "Feasible here", items: ["These people", "These systems", "These rules"], tone: "good" } }, caption: "Most failed projects were feasible somewhere. The assessment checks the right-hand side: the place it will actually be built and run." },
        { t: "p", text: "It is also the cheapest moment to be wrong. Here, in discovery, dropping an option costs a paragraph. In BUILD, it costs weeks of work, a rewrite and an awkward conversation with the client. Every hour you spend here rating honestly is insurance against the much more expensive discovery that something you assumed was true is not." },
        { t: "p", text: "Finally, the assessment shapes everything after it. Only feasible options get estimated in 1.5.2; the conditions you write here travel all the way into the ADR in 1.5.4 and become things somebody must check by a date. If a condition is vague now, nobody will be able to tell later whether it was met." },
        { t: "pull", text: "Feasible somewhere is not the same as feasible here." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start from two artifacts from topic 1.4: the **architecture options** (1.4.4), each drawn as containers and flow with how it meets the quality targets, and the **spike results** (1.4.3), which answered the riskiest questions with data. The entry condition is simple: the architecture options have been accepted. You hand on one artifact — the **feasibility assessment** — to 1.5.2, where only the options rated feasible get estimated." },
        { t: "table", caption: "Inputs, outputs and people", head: ["", "What"], rows: [
          ["Comes in", "Architecture options (ARO-##), spike results (SPK-##)"],
          ["Goes out", "Feasibility assessment — one per option — and the tech lead’s review notes"],
          ["Accountable", "Tech lead — signs off the ratings"],
          ["Responsible", "Engineer — gathers the evidence, rates, writes the conditions"],
          ["Consulted", "Architect, Operations — who will run it, and is the platform ready?"],
          ["Informed", "Client contact"],
          ["Timebox", "2–4 hours; options can be rated in parallel"],
          ["Gate", "Feasibility Rated"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Feasibility assessment", sub: "1.5.1" }, around: [ { label: "Architecture options", sub: "ARO-## · 1.4.4", type: "store", dir: "in" }, { label: "Spike results", sub: "SPK-## · 1.4.3", type: "store", dir: "in" }, { label: "Engineer", sub: "Responsible", type: "person", link: "gathers evidence, rates, writes conditions" }, { label: "Tech lead", sub: "Accountable", type: "person", link: "signs off the ratings" }, { label: "Architect, Operations", sub: "Consulted", type: "person", link: "who will run it? is the platform ready?" }, { label: "Client contact", sub: "Informed", type: "person", dir: "out" }, { label: "1.5.2 Estimate", sub: "only feasible options", type: "system", dir: "out" } ] }, caption: "Everything around the assessment: two topic 1.4 artifacts come in, each person has one role, and only the options rated feasible go on to 1.5.2." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Three ratings, each with its evidence" },
        { t: "p", text: "Use a small scale — high, medium, low — and spend your effort on the evidence rather than on the scale. **High** means the risky parts have been proven by a spike or are well documented, and the conditions are few and in sight. **Medium** means it can probably be done, but at least one important question is still open. **Low** means a critical part is unproven or contradicted by evidence, or the conditions are unlikely to be met. A rating without a citation is an opinion; the criterion for this lesson is that *every rating cites spike results or docs*." },
        { t: "figure", fig: { kind: "stack", layers: [ { label: "High", sub: "Risky parts proven by a spike or well documented; conditions few and in sight" }, { label: "Medium", sub: "Can probably be done, but at least one important question is still open" }, { label: "Low", sub: "A critical part unproven or contradicted by evidence, or conditions unlikely to be met" } ] }, caption: "The three ratings. The scale is small on purpose; the effort goes into the evidence each rating cites." },
        { t: "h3", text: "Unknowns are risks until evidence says otherwise" },
        { t: "p", text: "The rule here is blunt: **an unknown is never rated as low risk.** If nobody has tried it, you don’t know it works, and “it’ll probably be fine” is exactly the optimism that sinks feasible-looking options. Write each remaining unknown down, say whether it was spiked, what was found, and what it means. If a remaining unknown is critical, the exception route is one more spike before you rate." },
        { t: "h3", text: "Quality attributes at risk" },
        { t: "p", text: "Feasibility is not only “does it work?” but “does it work *well enough*?”. Name which quality attributes — from ISO/IEC 25010: functional correctness, performance efficiency, reliability, security, maintainability and so on — are at risk for each option, and link them to your QA scenarios from topic 1.2. Model accuracy, where there is a model, is rated separately; security unknowns are rated as risks; platform readiness is checked." },
        { t: "figure", fig: { kind: "hub", center: "Does it work well enough?", items: [ { label: "Quality attributes at risk", icon: "rule", text: "Named in ISO/IEC 25010 terms: functional correctness, performance efficiency, reliability, security, maintainability." }, { label: "Linked to QA scenarios", icon: "link", text: "Each attribute at risk links to your QA scenarios from topic 1.2." }, { label: "Model accuracy", icon: "analytics", text: "Where there is a model, its accuracy is rated separately." }, { label: "Security unknowns", icon: "security", text: "Rated as risks." }, { label: "Platform readiness", icon: "dns", text: "Checked." } ] }, caption: "Feasibility is “does it work well enough?”, not only “does it work?”. Each of these is checked per option." },
        { t: "h3", text: "Skills, capacity and conditions" },
        { t: "p", text: "An option your team can’t yet build is not infeasible — it has a cost. The edge case is spelt out in the lesson: **skills missing → rate with the training or hire it needs.** Then write the conditions: the things that must be true for the rating to hold. A contract signed, an approval given, a vendor commitment, a skill in place. Each one specific, checkable and — where timing matters — dated." },
        { t: "figure", fig: { kind: "tree", root: "A condition", children: [ { label: "What it can be", children: [ { label: "A contract signed" }, { label: "An approval given" }, { label: "A vendor commitment" }, { label: "A skill in place" } ] }, { label: "What it must be", children: [ { label: "Specific" }, { label: "Checkable" }, { label: "Dated, where timing matters" } ] } ] }, caption: "What must be true for a rating to hold: the kinds of condition, and the tests every one of them must pass." },
        { t: "figure", fig: { kind: "knowledge", name: "Surface unknowns early" }, caption: "Surface unknowns early: an unknown found in discovery costs a paragraph; the same unknown found in BUILD costs a rewrite." },
        { t: "terms", items: [
          { term: "Feasibility", def: "Whether an option can be built *and run* here — with this team, these systems, these rules — and on what conditions." },
          { term: "Unknown", def: "A question about an option that evidence hasn’t answered yet. Rated as a risk until a spike or document resolves it." },
          { term: "Condition", def: "Something that must be true for a rating to hold — specific, checkable, and dated where timing matters." },
          { term: "Quality attribute at risk", def: "An ISO/IEC 25010 characteristic (for example reliability or functional correctness) that the option may not deliver to target." },
          { term: "Spike", def: "A short, time-boxed experiment that answers one question with data. Its result is the evidence a rating cites." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "figure", fig: { kind: "workflow", fid: "discover.decide.feasibility" }, caption: "Assess Technical Feasibility — gather, rate, write the conditions, then the tech lead’s call." },
        { t: "steps", items: [
          { title: "Gather the evidence and unknowns per option", text: "Put each architecture option at the top of its own page. Under it, list the spike results that support it (by SPK-## ID), the documents you relied on — vendor docs, API references, the option evaluation matrix — and every question that is still open. For each unknown, record whether it was spiked, what was found, and its impact. The output is the first draft of the feasibility assessment.", tip: "If an option has no spike evidence at all, that is itself a finding. Write it down rather than leaving the space blank." },
          { title: "Rate each option", text: "Give each option high, medium or low, in one line, followed by the evidence behind it. Then name the quality attributes at risk, using ISO/IEC 25010 terms and linking to your QA scenarios. Rate model accuracy separately from the rest, treat security unknowns as risks, and note whether the platform it needs is ready. Ratings link to SPK-## and ARO-## so anyone can check them.", tip: "Write the rating sentence last. If you write it first, you’ll find yourself collecting evidence to support it." },
          { title: "Write the skills and conditions", text: "List the skills and capacity each option needs against what the team has. Ask Operations who will run it and whether they can. Where a skill is missing, rate the option *with* the training or hire it needs rather than marking it down. Then write each rating’s conditions as checkable, dated facts: who must do what, by when. If an option is feasible only with a vendor commitment, that commitment becomes a condition.", tip: "Test each condition with one question: on the date, could two people independently agree whether it was met?" },
          { title: "Decide: is it feasible?", text: "Prepare the call for the tech lead: which options are feasible, and on what conditions. The tech lead signs off. Ratings without evidence go back to step 1 to be re-assessed. A condition outside the team’s control — a contract, a regulator, a vendor — is escalated to the tech lead and the client. If nothing is feasible, you stop and record why in the learning log." },
        ] },
        { t: "figure", fig: { kind: "lanes", lanes: ["Engineer", "Operations", "Tech lead", "Client"], steps: [ { lane: 0, label: "Gather evidence & unknowns", sub: "SPK-##, docs, open questions" }, { lane: 0, label: "Rate each option", sub: "high / medium / low + evidence" }, { lane: 1, label: "Who will run it?", sub: "and can they?" }, { lane: 0, label: "Write skills & conditions", sub: "checkable, dated" }, { lane: 2, label: "Sign off the ratings", flag: "ok" }, { lane: 3, label: "Condition outside the team’s control", sub: "escalated with the tech lead", flag: "wait" } ] }, caption: "Who does what in the four steps. The engineer does the work, Operations answers the “run” question, and the tech lead makes the call." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Two architecture options came out of topic 1.4. **Option A** runs an inbox watcher on the Microsoft 365 mailbox, a queue, extraction by a managed cloud document-AI service in the EU region, validation and customer matching, and creation of orders through the ERP import API; low-confidence orders go to a clerk review screen. **Option B** swaps the extraction for self-hosted open-source OCR and a rules engine, with the same review screen." },
        { t: "figure", fig: { kind: "context", center: { label: "Option A", sub: "inbox watcher → queue → extraction → validation → orders" }, around: [ { label: "Microsoft 365 mailbox", sub: "watched for orders", type: "external", dir: "in" }, { label: "Document-AI service", sub: "managed, EU region", type: "external", link: "extraction", dir: "both" }, { label: "ERP import API", sub: "orders created", type: "system", dir: "out" }, { label: "Clerk", sub: "review screen", type: "person", link: "low-confidence orders", dir: "out" } ] }, caption: "Option A and what it touches. Option B is the same picture with the document-AI service swapped for self-hosted open-source OCR and a rules engine." },
        { t: "p", text: "The evidence came from the spikes. SPK-2 showed the ERP import API sustaining 1,800 orders an hour — so the import path is no longer an unknown. SPK-1 on scanned PDFs was the decisive one: only one option passed." },
        { t: "figure", fig: { kind: "bars", unit: "% of lines read correctly", rows: [
          { label: "A — document-AI, generated PDFs", value: 96, max: 100, tone: "good" },
          { label: "A — document-AI, scanned PDFs", value: 88, max: 100, tone: "neutral" },
          { label: "B — open-source OCR, generated PDFs", value: 93, max: 100, tone: "neutral" },
          { label: "B — open-source OCR, scanned PDFs", value: 71, max: 100, tone: "bad", note: "the open question for B" },
        ] }, caption: "The evidence the ratings cite: sandbox trials and SPK-1. On generated PDFs both options are close; on scans they are not." },
        { t: "table", caption: "Northwind feasibility, per option", head: ["", "Option A — managed document-AI", "Option B — self-hosted OCR + rules"], rows: [
          ["Rating", "High", "Medium"],
          ["Evidence", "SPK-1 on scans: 88%; SPK-2: import API sustains 1,800 orders/hour", "SPK-1 on scans: 71%; SPK-2 as for A"],
          ["What the rating hangs on", "EU processing — the vendor must contract to it", "Scan accuracy unresolved"],
          ["Condition", "A signed DPA (data processing agreement) for EU processing", "—"],
          ["Constraint it must respect", "C-02: data stays in the EU", "C-02: met by self-hosting"],
        ] },
        { t: "callout", tone: "case", title: "Northwind", text: "A: high, on condition of a signed DPA for EU processing. B: medium — scan accuracy unresolved." },
        { t: "p", text: "Notice how the condition on A comes straight from a confirmed constraint from topic 1.1 — C-02, data stays in the EU. A cloud service is only feasible here if the contract says it processes the data in the EU. That condition will reappear, dated, in the ADR." },
        { t: "figure", fig: { kind: "template", id: "feasibility-assessment" }, caption: "The feasibility assessment — rating, unknowns and how they were resolved, quality attributes at risk, skills and capacity, conditions." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Your agent is useful here in two ways: as a clerk that gathers the evidence per option into one place, and as a sceptic that challenges your ratings. The lesson’s own guidance is to use it for *challenging the ratings*. It should never be the one that decides an option is feasible." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to argue against each option’s feasibility using only the evidence in your pack. Its objections become your conditions — or your reasons to re-rate." },
        { t: "prompt", title: "Gather and rate", text: "I’m assessing the technical feasibility of the architecture options below. Draft and check; I decide.\n\nFor each option:\n1. List the spike results (by SPK-## ID) and documents that support it.\n2. List every remaining unknown: was it spiked, what was found, what is its impact?\n3. Propose a rating — high, medium or low — and cite the evidence for it.\n4. Name the ISO/IEC 25010 quality attributes at risk, linked to my QA scenarios.\n5. List the skills and capacity the option needs against what my team has.\n\nRules: never rate an unknown as low risk. If something hasn’t been tested, say so. Ask me rather than guess.\n\nArchitecture options and spike results: [paste]" },
        { t: "p", text: "**What to check in its answer:** every rating points at a real SPK-## or document you can open; no unknown has been quietly turned into “low risk”; the quality attributes match your QA scenarios, not a generic list; and the skills list reflects your actual team, not an imagined one." },
        { t: "prompt", title: "Argue against it", text: "Act as a sceptical architect. Using only the evidence in the feasibility assessment below, give me the three strongest reasons each option might NOT be feasible here — with this team, these systems and these constraints. For each, say what evidence would settle it and whether it should become a condition, a re-rating or one more spike.\n\nFeasibility assessment: [paste]" },
        { t: "p", text: "**What to check:** that each objection is grounded in your pack rather than in general worries; turn the good ones into conditions or re-ratings, and write down why you set aside the rest." },
        { t: "figure", fig: { kind: "cycle", center: "Draft and check; I decide", steps: [ { label: "Agent gathers evidence", text: "Spike results and documents per option, every unknown listed." }, { label: "Agent proposes ratings", text: "High, medium or low, each citing evidence; no unknown rated low risk." }, { label: "Agent argues against", text: "The three strongest reasons each option might not be feasible here." }, { label: "You decide", text: "Turn the good objections into conditions, re-ratings or one more spike; write why you set aside the rest." } ] }, caption: "The agent as clerk and sceptic. It never decides an option is feasible; its objections feed your conditions and re-ratings." },

        { t: "h", text: "Common mistakes" },
        { t: "contrast", label: "A condition", bad: { title: "Vague", text: "“Subject to legal approval of the vendor.”" }, good: { title: "Checkable and dated", text: "“Data processing agreement for EU processing signed by the client and the vendor by [date]. Owner: tech lead. Checked by: copy on file in the document repository.”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [ { text: "Data processing agreement for EU processing", label: "What" }, { text: " signed by the client and the vendor", label: "Who" }, { text: " by [date].", label: "When" }, { text: " Owner: tech lead.", label: "Owner" }, { text: " Checked by: copy on file in the document repository.", label: "How it is checked" } ] }, caption: "The checkable condition, taken apart. On the date, two people could independently agree whether it was met." },
        { t: "contrast", label: "A rating", bad: { title: "Opinion", text: "“Option B: should be fine, OCR is a mature technology.”" }, good: { title: "Evidence", text: "“Option B: medium. SPK-1 read 71% of lines correctly on scanned PDFs; scan accuracy is unresolved. Quality attribute at risk: functional correctness (QA-1).”" } },
        { t: "pitfalls", items: [
          { trap: "Rating an unspiked unknown as low risk because the technology is popular.", fix: "Rate it as a risk, and write what would resolve it — usually one more spike." },
          { trap: "Conditions too vague to check (“pending approvals”).", fix: "Rewrite them as dated, checkable facts with an owner." },
          { trap: "Marking an option down because the team lacks a skill.", fix: "Rate it with the training or hire it needs; the cost shows up in 1.5.2." },
          { trap: "Assessing only the favourite option in depth.", fix: "Rate every option on the same evidence. If there is one clear option, assess it *and* the fallback." },
          { trap: "Forgetting “run” in “build and run”.", fix: "Ask Operations who will run it, and whether the platform is ready." },
        ] },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of the happy path", head: ["Situation", "What you do"], rows: [
          ["Ratings unevidenced", "Rework: back to step 1 and re-assess with the evidence"],
          ["Feasible only with a vendor commitment", "Make the commitment a condition"],
          ["Remaining unknown is critical", "One more spike first, then rate"],
          ["Skills missing", "Rate with the training or hire it needs"],
          ["Condition outside the team’s control", "Escalate to the tech lead and the client"],
          ["Only one clear option", "Assess it and the fallback"],
          ["Nothing feasible", "Stop and record why — in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [ { id: "q1", q: "Does every rating cite spike results or docs?", yes: "q2", no: "r1" }, { id: "r1", result: "Rework: back to step 1 and re-assess with the evidence", tone: "bad" }, { id: "q2", q: "Is a remaining unknown critical?", yes: "r2", no: "q3" }, { id: "r2", result: "One more spike first, then rate", tone: "neutral" }, { id: "q3", q: "Are skills missing?", yes: "r3", no: "q4" }, { id: "r3", result: "Rate with the training or hire it needs", tone: "neutral" }, { id: "q4", q: "Is it feasible only with a vendor commitment?", yes: "r4", no: "q5" }, { id: "r4", result: "Make the commitment a condition", tone: "neutral" }, { id: "q5", q: "Is a condition outside the team’s control?", yes: "r5", no: "q6" }, { id: "r5", result: "Escalate to the tech lead and the client", tone: "neutral" }, { id: "q6", q: "Is any option feasible?", yes: "q7", no: "r6" }, { id: "r6", result: "Stop and record why — in the learning log", tone: "bad" }, { id: "q7", q: "Is there only one clear option?", yes: "r7", no: "r8" }, { id: "r7", result: "Assess it and the fallback", tone: "neutral" }, { id: "r8", result: "The tech lead signs off: Feasibility Rated", tone: "good" } ] }, caption: "The routes out of the happy path as a walk-through. Every answer leads to the action the table gives." },
        { t: "callout", tone: "warn", title: "An unknown is never low risk", text: "If you don’t know, you can’t rate it low. Optimism about unknowns is the most common way a feasible-looking option fails." },
        { t: "note", text: "“Nothing feasible” is not a failure of the lesson. It is the lesson doing its job — a stop recorded in discovery is far cheaper than a stop discovered in BUILD." },
        { t: "figure", fig: { kind: "knowledge", name: "Pre-mortem" }, caption: "The pre-mortem: imagine it failed, then ask why — before anyone commits. Used here to find the conditions; used again in 1.5.2 to find the risks." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Every rating cites spike results or docs", "Conditions are specific, checkable and dated", "Missing skills are rated with the training or hire they need", "Quality attributes at risk are named and linked to the QA scenarios", "The tech lead has signed off the ratings"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Feasibility Rated", items: [
          "Each option is rated high, medium or low with evidence",
          "Every rating links to SPK-## and ARO-##",
          "No unknown is rated as low risk",
          "Quality attributes at risk are named per option",
          "Skills and capacity are checked, with training or hires where needed",
          "Conditions are written as specific, checkable, dated facts",
          "Conditions outside our control are escalated",
          "The tech lead has signed off",
        ] },
        { t: "try", text: "Rate option A’s feasibility and write two dated conditions. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.5.2 ───────────────────────────── */
    {
      id: "discover.decide.estimate", fid: "discover.decide.estimate", code: "1.5.2", title: "Estimate Effort, Risk & Cost", minutes: 11,
      blocks: [
        { t: "lead", text: "A single number is a promise you can’t keep. This lesson gives each feasible option an honest effort *range*, its running cost, and a risk register where every risk has a likelihood, an impact, an owner and a mitigation — so the choice includes what it costs." },
        { t: "tldr", items: [
          "Break each feasible option into work items small enough to picture.",
          "Estimate each item as low / likely / high days, with the basis for each — never a single number.",
          "Add what it costs to run, at normal volume and at peak.",
          "Run a pre-mortem; every risk it finds gets a likelihood, an impact, an owner and a mitigation.",
          "Risks above the tech lead’s appetite go to the client — escalated, never hidden.",
        ] },
        { t: "p", text: "The job: *help me say how big each option is and what could go wrong, without false precision.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Two options can be equally feasible and wildly different in size. Until you’ve put a size and a price on each, any comparison is guesswork — and the first person to ask “how long?” will get whichever number was said out loud first. That number then hardens into a promise." },
        { t: "p", text: "The two concerns this lesson guards against are named plainly: **estimates treated as promises**, and **run cost forgotten**. The first is solved with ranges that say how much you still don’t know. The second is solved by putting the monthly cost of running the thing next to the cost of building it, because the cheaper option to build is not always the cheaper option to own." },
        { t: "p", text: "Risk belongs here too, because risk is the part of the cost you can’t see yet. A risk register with owners turns “what could go wrong” from a mood into a list of things somebody is watching." },
        { t: "figure", fig: { kind: "tree", root: "What this lesson guards against", children: [ { label: "Estimates treated as promises", text: "Solved with ranges that say how much you still don’t know." }, { label: "Run cost forgotten", text: "Solved by putting the monthly cost of running it next to the cost of building it." }, { label: "Risk you can’t see yet", text: "Solved by a risk register with owners — a list of things somebody is watching." } ] }, caption: "Three ways a comparison turns into guesswork, and what fixes each: ranges, a run-cost row and an owned risk register." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start from the **feasibility assessment** (1.5.1) and the **architecture options** (1.4.4). The entry condition is that feasibility has been rated — only feasible options are estimated. You produce two artifacts, the **effort estimate** and the **risk register**, which go to 1.5.3 to be compared side by side." },
        { t: "table", caption: "Inputs, outputs and people", head: ["", "What"], rows: [
          ["Comes in", "Feasibility assessment, architecture options (ARO-##)"],
          ["Goes out", "Effort estimate (EST-##) and risk register (RSK-##), both linked to ARO-##"],
          ["Accountable", "Tech lead — accepts the estimates; risks above appetite go to the client"],
          ["Responsible", "Engineer — breaks down the work, estimates, runs the pre-mortem"],
          ["Consulted", "Architect, Operations — run and support cost, hosting at peak"],
          ["Informed", "Client contact"],
          ["Tools", "Spreadsheet model, risk register"],
          ["Timebox", "½ day — estimating and risk-finding run in parallel"],
          ["Gate", "Estimates Reviewed"],
        ] },
        { t: "figure", fig: { kind: "flow", steps: [ { label: "Feasibility assessment", sub: "1.5.1 · entry: rated" }, { label: "Only feasible options", sub: "ARO-## · 1.4.4" }, { label: "Effort estimate", sub: "EST-##" }, { label: "Risk register", sub: "RSK-##" }, { label: "1.5.3 Compare", sub: "side by side" } ] }, caption: "Where the lesson sits: only feasible options are estimated, and both outputs, linked to ARO-##, go on to 1.5.3." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Three-point estimates" },
        { t: "p", text: "For each work item you give three numbers: **low** (it goes well), **likely** (it goes as you expect) and **high** (the things you can foresee go wrong). Each comes with its **basis** — the reason you believe it: a similar piece of work done before, a spike’s code you can reuse, reference stories. A range without a basis is just a wider guess; the criterion is *ranges with a basis, never single numbers*." },
        { t: "p", text: "If you need one planning figure from a three-point estimate, the standard PERT formula weights the likely value: (low + 4 × likely + high) ÷ 6. The spread, (high − low) ÷ 6, is a rough measure of how uncertain the item is. Use these as summaries; keep the range visible." },
        { t: "figure", fig: { kind: "knowledge", name: "Three-point estimation" }, caption: "Three-point estimation: low, likely and high, each with its basis." },
        { t: "h3", text: "The cone of uncertainty" },
        { t: "p", text: "Early in a piece of work, the honest range around any estimate is wide; it narrows as you learn — as requirements settle, designs firm up and code gets written. Discovery sits near the wide end. Saying so is not weakness; it is accuracy. Where an item is very uncertain, the alternate route is a wide range *plus* a spike to narrow it." },
        { t: "figure", fig: { kind: "knowledge", name: "Cone of uncertainty" }, caption: "The cone of uncertainty: the range narrows as you learn. Here, in discovery, it is still wide." },
        { t: "h3", text: "Relative estimation and reference data" },
        { t: "p", text: "People are better at comparing than at sizing from nothing. “This is about twice the inbox watcher” is often more reliable than “this is nine days”. And where you have **reference data from past projects** — how long a similar integration actually took — use it to check the range. That is the edge case the lesson names." },
        { t: "h3", text: "Risk, the ISO 31000 way" },
        { t: "p", text: "ISO 31000 describes risk management as identifying risks, analysing them (how likely, how bad), evaluating them against your appetite, and treating them. The treatment options in the register are the familiar four: **avoid** (change the plan so the risk can’t happen), **reduce** (make it less likely or less harmful), **share** (pass part of it to someone else, such as a vendor or insurer) and **accept** (live with it, knowingly). Write each risk as *cause → event → effect* so its mitigation is obvious." },
        { t: "figure", fig: { kind: "tree", root: "ISO 31000 risk management", children: [ { label: "Identify", text: "Find the risks." }, { label: "Analyse", text: "How likely, how bad." }, { label: "Evaluate", text: "Against your appetite." }, { label: "Treat", children: [ { label: "Avoid", text: "Change the plan so the risk can’t happen." }, { label: "Reduce", text: "Make it less likely or less harmful." }, { label: "Share", text: "Pass part of it to someone else, such as a vendor or insurer." }, { label: "Accept", text: "Live with it, knowingly." } ] } ] }, caption: "Risk the ISO 31000 way: four activities, and the four treatments a register row can choose from." },
        { t: "terms", items: [
          { term: "Three-point estimate", def: "Low, likely and high values for one work item, each with its basis." },
          { term: "Basis", def: "Why you believe a number — past work, spike code, reference stories, vendor pricing." },
          { term: "Run cost", def: "What the option costs each month to operate and support — at normal volume and at peak." },
          { term: "Risk appetite", def: "How much risk the decision-maker is willing to carry. Above it, the risk is escalated." },
          { term: "Pre-mortem", def: "Imagine it is six months later and the work has failed; write down why. The answers become risks." },
          { term: "Risk rating", def: "Likelihood × impact, each on a 1–5 scale in the register." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "figure", fig: { kind: "workflow", fid: "discover.decide.estimate" }, caption: "Estimate Effort, Risk & Cost — break down, range, pre-mortem, then the appetite call." },
        { t: "steps", items: [
          { title: "Break each option into work items", text: "For every feasible option, list the work small enough to picture: integration, logic, UI, tests, deployment, monitoring. A good work item is one an engineer can describe in a sentence and imagine finishing. If it’s bigger than a couple of weeks, break it again. Use the architecture option’s containers as a starting list — each box usually becomes one or more items.", tip: "Don’t forget the unglamorous items: tests, deployment, monitoring and the review screen are real work." },
          { title: "Estimate three-point ranges and the run cost", text: "For each item, write low, likely and high days, with a basis and a confidence. Then add the monthly run and support cost — hosting, per-use fees, licences, support time — at normal and at peak volume. Flag the widest ranges: they tell you where the uncertainty lives. Check against reference data from past projects where you have it. Work in a spreadsheet so the totals and the basis sit side by side.", tip: "Sum lows and highs for an option’s total range. Don’t quote the sum of the likelies as “the” estimate." },
          { title: "Run a pre-mortem and rate the risks", text: "Gather the engineer, the architect and someone from Operations. Say: “It’s six months later and this failed — why?” Everyone writes reasons silently, then you share them. Turn each answer into a risk-register row: cause → event → effect, likelihood (1–5), impact (1–5), rating, owner, treatment and mitigation. Include security failure scenarios and vendor and dependency risks. A risk owned outside the team gets a named owner on the client side.", tip: "Writing silently first stops the loudest voice setting the list." },
          { title: "Decide: is it within appetite?", text: "Summarise effort, run cost and the top risks per option for the tech lead, and flag anything beyond normal appetite. The tech lead accepts the estimates. Ranges without a basis go back to step 2 to be re-estimated. A risk above the tech lead’s appetite goes to the client. If every option is too big, you stop: back to framing, or scope down — recorded in the learning log." },
        ] },
        { t: "figure", fig: { kind: "lanes", lanes: ["Engineer", "Architect & Operations", "Tech lead", "Client"], steps: [ { lane: 0, label: "Break options into work items", sub: "integration, logic, UI, tests, deployment, monitoring" }, { lane: 0, label: "Three-point ranges + run cost", sub: "basis and confidence" }, { lane: 1, label: "Pre-mortem", sub: "write reasons silently, then share" }, { lane: 0, label: "Rate the risks", sub: "likelihood × impact, owner, treatment" }, { lane: 2, label: "Accept the estimates", flag: "ok" }, { lane: 3, label: "Risks above appetite", sub: "escalated, never hidden", flag: "wait" } ] }, caption: "Who does what. The engineer leads, the architect and Operations join the pre-mortem, the tech lead accepts, and risks above appetite go to the client." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "The engineer broke Option A into work items and estimated each with a basis. The rows below come from Northwind’s effort estimate." },
        { t: "table", caption: "Northwind effort estimate — Option A (from EST)", head: ["Work item", "Low", "Likely", "High", "Basis", "Confidence"], rows: [
          ["Inbox watcher + queue", "3 days", "5 days", "8 days", "Similar Graph integration last year", "High"],
          ["Extraction + validation + customer match", "8 days", "12 days", "20 days", "Spike SPK-1 code as reference", "Medium"],
          ["Clerk review UI", "5 days", "8 days", "12 days", "Reference stories", "Medium"],
          ["Run cost (per month)", "€300", "€550", "€900", "Vendor pricing × peak volume", "Medium"],
        ] },
        { t: "figure", fig: { kind: "ranges", unit: "days", rows: [
          { label: "A — inbox watcher + queue", low: 3, likely: 5, high: 8 },
          { label: "A — extraction, validation, match", low: 8, likely: 12, high: 20 },
          { label: "A — clerk review UI", low: 5, likely: 8, high: 12 },
          { label: "Option A — total", low: 16, high: 40 },
          { label: "Option B — total", low: 25, high: 55 },
        ] }, caption: "Estimates as ranges. The width is information: the extraction item is the widest, so that is where the uncertainty lives." },
        { t: "p", text: "Two things stand out. First, the widest range is the extraction work — exactly the part the spikes were about, and exactly where the confidence is only medium. Second, Option B is bigger to build (25–55 days) but cheaper to run (about €150 a month against A’s ~€550). That tension is what 1.5.3 will have to weigh." },
        { t: "figure", fig: { kind: "split", left: { title: "Option A", items: ["Smaller to build: 16–40 days", "Dearer to run: ~€550 a month"], tone: "fact" }, right: { title: "Option B", items: ["Bigger to build: 25–55 days", "Cheaper to run: about €150 a month"], tone: "fact" } }, caption: "The tension 1.5.3 has to weigh: the cheaper option to build is not the cheaper option to own." },
        { t: "p", text: "If you wanted a single planning figure for the inbox watcher, PERT gives (3 + 4 × 5 + 8) ÷ 6 ≈ 5.2 days. Useful for a plan; never a promise." },
        { t: "callout", tone: "case", title: "Northwind", text: "A: 16–40 days, ~€550 a month at peak. RSK-01 vendor cost at peak, RSK-02 low-confidence orders swamp clerks — each with an owner." },
        { t: "figure", fig: { kind: "tree", root: "Pre-mortem: why might Option A fail?", children: [ { label: "RSK-01 Vendor cost at peak", text: "The vendor’s per-page cost at peak — the flip side of A’s run cost." }, { label: "RSK-02 Clerks swamped", text: "Too many orders fall below the confidence threshold and the clerks are back to re-typing — the flip side of the review screen." } ] }, caption: "The two risks Northwind’s pre-mortem surfaced. Each is the shadow of a design choice, and each has an owner." },
        { t: "p", text: "The pre-mortem surfaced the risks. RSK-01 — the vendor’s per-page cost at peak — is the flip side of A’s run cost. RSK-02 — low-confidence orders swamping the clerks — is the flip side of the review screen: if too many orders fall below the confidence threshold, the clerks are back to re-typing. Both have an owner. The register’s example row shows the full shape of a risk:" },
        { t: "table", caption: "A risk-register row in full (the template’s example)", head: ["ID", "Risk (cause → event → effect)", "L", "I", "Rating", "Owner", "Treatment", "Mitigation"], rows: [
          ["R-01", "Poor scans → parsing errors → wrong orders shipped", "3", "4", "12", "Ops manager", "Reduce", "Human review below confidence 90%"],
        ] },
        { t: "figure", fig: { kind: "anatomy", parts: [ { text: "Poor scans", label: "Cause" }, { text: " → parsing errors", label: "Event" }, { text: " → wrong orders shipped.", label: "Effect" }, { text: " Likelihood 3 × impact 4 = 12.", label: "Rating" }, { text: " Owner: Ops manager.", label: "Owner" }, { text: " Reduce", label: "Treatment" }, { text: ": human review below confidence 90%.", label: "Mitigation" } ] }, caption: "The example row read as one sentence. Written as cause → event → effect, the mitigation is obvious." },
        { t: "figure", fig: { kind: "template", id: "effort-estimate" }, caption: "The effort estimate — work item, low / likely / high, basis and confidence, with run cost as its own row." },
        { t: "figure", fig: { kind: "template", id: "risk-register" }, caption: "The risk register — likelihood, impact, owner, treatment, mitigation." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "The lesson suggests the agent for *breaking down work* — it is good at listing the items people forget. It is less good at the numbers: like people, it tends to estimate the happy path. You own the ranges and the owners." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to break the option into work items and propose three-point ranges with a basis for each, then to run a pre-mortem. Challenge the “likely” numbers — agents, like people, tend to estimate the happy path." },
        { t: "prompt", title: "Break down and range", text: "Here is a feasible architecture option and its feasibility assessment. Draft and check; I decide.\n\n1. Break it into work items small enough to picture: integration, logic, UI, tests, deployment, monitoring.\n2. For each item, propose low / likely / high days. For each number, state the basis you are assuming — and mark it ASSUMED if you have no evidence from my material.\n3. Add monthly run and support cost at normal volume and at peak, with how you worked it out.\n4. Flag the three widest ranges and say what would narrow each.\n\nNever give a single number. Ask me for reference data from past projects rather than inventing it.\n\nOption and assessment: [paste]" },
        { t: "p", text: "**What to check:** every basis is something you recognise — past work, spike code, vendor pricing — not an invented benchmark; nothing marked ASSUMED stays that way without your say-so; the run cost includes peak volume; tests, deployment and monitoring are on the list." },
        { t: "prompt", title: "Pre-mortem", text: "It is six months after go-live and this option has failed. Write the ten most plausible reasons why, drawing on the architecture, the feasibility conditions and the risks below. Include security failures and vendor or dependency failures. Then turn each into a risk-register row: cause → event → effect, likelihood 1–5, impact 1–5, suggested treatment (avoid / reduce / share / accept) and mitigation. Leave the owner blank for me to fill.\n\nMaterial: [paste]" },
        { t: "p", text: "**What to check:** that the likelihood and impact numbers are justified, not decorative; that you, not the agent, name every owner; and that anything above appetite is flagged for the client." },
        { t: "figure", fig: { kind: "cycle", center: "You own the ranges and the owners", steps: [ { label: "Agent breaks down the work", text: "Integration, logic, UI, tests, deployment, monitoring — the items people forget." }, { label: "Agent proposes ranges", text: "Low / likely / high with a basis; ASSUMED where your material has no evidence." }, { label: "You challenge", text: "The “likely” numbers — agents, like people, estimate the happy path." }, { label: "Agent runs a pre-mortem", text: "Plausible reasons it failed, as risk rows with the owner left blank." }, { label: "You name the owners", text: "And flag anything above appetite for the client." } ] }, caption: "The agent lists and drafts; you challenge and own. Go round again until nothing marked ASSUMED stays that way without your say-so." },

        { t: "h", text: "Common mistakes" },
        { t: "contrast", label: "An estimate", bad: { title: "False precision", text: "“The extraction work will take 12 days.”" }, good: { title: "An honest range", text: "“Extraction, validation and customer match: 8 / 12 / 20 days. Basis: the SPK-1 spike code as a reference. Confidence: medium — this is the widest range in the estimate.”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [ { text: "Extraction, validation and customer match:", label: "Work item" }, { text: " 8 / 12 / 20 days.", label: "Low / likely / high" }, { text: " Basis: the SPK-1 spike code as a reference.", label: "Basis" }, { text: " Confidence: medium", label: "Confidence" }, { text: " — this is the widest range in the estimate.", label: "Flag" } ] }, caption: "An honest range, taken apart: every part a single number leaves out." },
        { t: "contrast", label: "A risk", bad: { title: "A worry", text: "“The vendor might be expensive.”" }, good: { title: "An owned risk", text: "“RSK-01: per-page pricing × peak volume → monthly cost above budget → pressure to drop the review step. Owner named; mitigation and treatment recorded.”" } },
        { t: "pitfalls", items: [
          { trap: "Quoting a single number because someone asked for one.", fix: "Convert it to a three-point range with a basis — and explain what the width means." },
          { trap: "Estimating the build and forgetting to run it.", fix: "Add monthly run and support cost, at normal and at peak, as its own row." },
          { trap: "Risks without owners.", fix: "Name an owner or escalate. An unowned risk is a risk nobody manages." },
          { trap: "Hiding a risk that is above appetite to keep the option alive.", fix: "Escalate it to the client. Risks above appetite are escalated, never hidden." },
          { trap: "Treating the likely numbers as safe because they look modest.", fix: "Ask what the high number assumes, and whether it really covers the foreseeable trouble." },
        ] },
        { t: "callout", tone: "key", title: "Ranges, never single numbers", text: "Prefer ranges to false precision. The cone of uncertainty narrows as you learn — here, in discovery, it is still wide, and saying so is honest." },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of the happy path", head: ["Situation", "What you do"], rows: [
          ["Ranges without a basis", "Rework: back to step 2 and re-estimate"],
          ["Very uncertain item", "Wide range, plus a spike to narrow it"],
          ["Reference data from past projects", "Use it to check the range"],
          ["Risk owned outside the team", "Named owner on the client side"],
          ["Risk above the tech lead’s appetite", "Escalate to the client"],
          ["Small option", "One range and a short risk list"],
          ["An option can’t be estimated at all", "Treat it as unresolved — it needs more discovery before it can be compared"],
          ["Every option too big", "Stop: back to framing or scope down — recorded in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [ { id: "q1", q: "Does every range have a basis?", yes: "q2", no: "r1" }, { id: "r1", result: "Rework: back to step 2 and re-estimate", tone: "bad" }, { id: "q2", q: "Can the option be estimated at all?", yes: "q3", no: "r2" }, { id: "r2", result: "Treat it as unresolved — it needs more discovery before it can be compared", tone: "neutral" }, { id: "q3", q: "Is an item very uncertain?", yes: "r3", no: "q4" }, { id: "r3", result: "Wide range, plus a spike to narrow it", tone: "neutral" }, { id: "q4", q: "Is every option too big?", yes: "r4", no: "q5" }, { id: "r4", result: "Stop: back to framing or scope down — recorded in the learning log", tone: "bad" }, { id: "q5", q: "Is a risk owned outside the team?", yes: "r5", no: "q6" }, { id: "r5", result: "Named owner on the client side", tone: "neutral" }, { id: "q6", q: "Is a risk above the tech lead’s appetite?", yes: "r6", no: "r7" }, { id: "r6", result: "Escalate to the client", tone: "neutral" }, { id: "r7", result: "The tech lead accepts: Estimates Reviewed", tone: "good" } ] }, caption: "The routes out of the happy path as a walk-through. Note the two stops: an option that can’t be estimated, and every option too big." },
        { t: "note", text: "Estimates made in this topic are checked against actuals in BUILD, and the accuracy goes in the learning log. That is how your team’s next ranges get narrower." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Ranges with a basis, never single numbers", "Run cost included, at normal and peak", "Every risk has likelihood, impact, owner and mitigation", "The widest ranges are flagged with what would narrow them", "EST-## and RSK-## link to ARO-##"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Estimates Reviewed", items: [
          "Every feasible option is broken into work items",
          "Every item has low / likely / high with its basis",
          "Monthly run and support cost is included, at peak",
          "The widest ranges are flagged",
          "A pre-mortem has been run",
          "Every risk has likelihood, impact, owner and mitigation",
          "Risks above appetite have gone to the client",
          "The tech lead has reviewed the estimates",
        ] },
        { t: "try", text: "Estimate three work items for option A as low / likely / high with a basis, and add two risks with owners. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.5.3 ───────────────────────────── */
    {
      id: "discover.decide.compare", fid: "discover.decide.compare", code: "1.5.3", title: "Compare Options & Recommend", minutes: 10,
      blocks: [
        { t: "lead", text: "You have everything now: how well each option meets the targets, whether it’s feasible, what it costs to build and run, and what could go wrong. This lesson puts the options side by side on the same rows and makes one clear recommendation the tech lead can accept or challenge." },
        { t: "tldr", items: [
          "Compare every option on the same rows: targets met, feasibility, effort range, run cost, top risk, reversibility.",
          "Name what each choice gives up — in a sentence, in plain words.",
          "Recommend one option, say why, say how reversible it is, and make it conditional if it depends on a condition.",
          "Recommend, don’t advocate: show the losing options fairly.",
          "In a close call, recommend the option that is cheaper to reverse.",
        ] },
        { t: "p", text: "The job: *help me recommend one approach and explain exactly why, including what we give up.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Up to now each artifact has looked at one dimension at a time — the evaluation matrix at the quality targets, the feasibility assessment at whether it can be done, the estimate at size and cost, the register at risk. A decision needs them on one page. Without that page, people decide on whichever dimension they personally care about most." },
        { t: "figure", fig: { kind: "hub", center: "One page for the decision", items: [ { label: "Option evaluation matrix", icon: "analytics", text: "Looked at the quality targets." }, { label: "Feasibility assessment", icon: "fact_check", text: "Looked at whether it can be done." }, { label: "Effort estimate", icon: "timer", text: "Looked at size and cost." }, { label: "Risk register", icon: "warning", text: "Looked at risk." } ] }, caption: "Each earlier artifact looked at one dimension. The comparison puts all four on one page, so nobody decides on the one they personally care about most." },
        { t: "p", text: "The lesson guards against two concerns: **hiding the trade-offs**, and **recommending by habit** — picking the technology you used last time, or the newest one, rather than the one the evidence supports. A recommendation that hides what it gives up will be overturned the first time someone finds out; one that states it plainly can be accepted with open eyes." },
        { t: "pull", text: "Every choice gives something up. Say what, before someone else does." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start from four inputs: the **option evaluation matrix** (1.4.2), the **feasibility assessment** (1.5.1), the **effort estimate** and the **risk register** (1.5.2). The entry condition is that the estimates and risks have been reviewed. You produce the **option comparison & recommendation**, which goes to 1.5.4 to be recorded as the ADR." },
        { t: "table", caption: "Inputs, outputs and people", head: ["", "What"], rows: [
          ["Comes in", "Option evaluation matrix, feasibility assessment, effort estimate, risk register"],
          ["Goes out", "Option comparison & recommendation, linking ARO-##, EST-## and RSK-##"],
          ["Accountable", "Tech lead — accepts or challenges the recommendation"],
          ["Responsible", "Engineer — builds the comparison and writes the recommendation"],
          ["Consulted", "Architect"],
          ["Informed", "Client contact — who decides trade-offs that touch their targets"],
          ["Timebox", "2–4 hours"],
          ["Gate", "Recommendation Accepted"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Option comparison & recommendation", sub: "1.5.3" }, around: [ { label: "Option evaluation matrix", sub: "1.4.2", type: "store", dir: "in" }, { label: "Feasibility assessment", sub: "1.5.1", type: "store", dir: "in" }, { label: "Effort estimate", sub: "EST-## · 1.5.2", type: "store", dir: "in" }, { label: "Risk register", sub: "RSK-## · 1.5.2", type: "store", dir: "in" }, { label: "Engineer", sub: "Responsible", type: "person", link: "builds the comparison, writes the recommendation" }, { label: "Tech lead", sub: "Accountable", type: "person", link: "accepts or challenges" }, { label: "Architect", sub: "Consulted", type: "person" }, { label: "Client contact", sub: "Informed", type: "person", link: "decides trade-offs that touch their targets" }, { label: "1.5.4 ADR", sub: "recorded as the decision", type: "system", dir: "out" } ] }, caption: "Four artifacts come in, one recommendation goes out to be recorded as the ADR. The client decides any trade-off that touches their targets." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Same rows for every option" },
        { t: "p", text: "The first criterion is that *every option is compared on the same criteria*. If Option A has a row for accuracy and Option B has a row for cost, you haven’t compared them; you’ve described them. Use fixed rows — quality targets met, feasibility, effort range, run cost, top risk, reversibility — and fill every cell for every option, including “do nothing” where it is still on the table. A single option is compared with doing nothing." },
        { t: "figure", fig: { kind: "tree", root: "Fixed rows, for every option", children: [ { label: "Quality targets met", text: "By QA-##." }, { label: "Feasibility rating" }, { label: "Effort range", text: "In days." }, { label: "Run cost", text: "In euros a month." }, { label: "Top risk" }, { label: "Reversibility" } ] }, caption: "The same six rows for every option, including “do nothing” where it is still on the table. An empty cell is a gap to fill, not a cell to skip." },
        { t: "h3", text: "Weighted comparison and trade-off analysis" },
        { t: "p", text: "A weighted comparison multiplies each option’s score on a criterion by that criterion’s weight and adds them up. It is useful for making priorities explicit — as long as the weights were set *before* the scores were seen, as they were in topic 1.4. But a weighted total is a summary, not a verdict. Trade-off analysis asks the harder question: where does improving one quality attribute cost you another? Accuracy against run cost; speed to build against vendor dependency; control against upkeep." },
        { t: "figure", fig: { kind: "knowledge", name: "Trade-off analysis" }, caption: "Trade-off analysis: improving one quality attribute usually costs another. Name the cost." },
        { t: "h3", text: "Reversibility" },
        { t: "p", text: "Some decisions are easy to undo; others lock you in. The criterion is that *the recommendation is reversible, or says why not*. Reversibility is often something you can design in — putting a dependency behind an adapter, so it can be swapped later — and it changes how much certainty you need. When two options are close, the lesson’s alternate route is clear: **recommend the cheaper-to-reverse option**, with the reason." },
        { t: "h3", text: "Conditional recommendations" },
        { t: "p", text: "If the recommendation depends on a condition from the feasibility assessment, it must say so. “Recommend A, on condition that X by date Y” is honest; “Recommend A” with X buried on page four is not. The condition then travels into the ADR." },
        { t: "terms", items: [
          { term: "Option comparison", def: "One page that puts every option on the same rows: targets, feasibility, effort, run cost, top risk, reversibility." },
          { term: "Trade-off", def: "What choosing one option gives up compared with the others — stated in a sentence." },
          { term: "Reversibility", def: "How hard it is to change the decision later. Often designed in, for example with an adapter." },
          { term: "Weighted comparison", def: "Scores × pre-agreed weights, summed. A summary of priorities, not a verdict." },
          { term: "Recommend, don’t advocate", def: "Present the losing options fairly, so the decision-maker can disagree with you on the evidence." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "figure", fig: { kind: "workflow", fid: "discover.decide.compare" }, caption: "Compare Options & Recommend — side by side, trade-offs, recommendation, then the tech lead’s review." },
        { t: "steps", items: [
          { title: "Put the options side by side", text: "Build one table with a column per option and fixed rows: quality targets met (by QA-##), feasibility rating, effort range, run cost, top risk, and reversibility. Pull every cell from its source artifact — the evaluation matrix, the feasibility assessment, the estimate, the register — and link it. If a cell is empty, that is a gap to fill before you go further.", tip: "Use the same units in every column: days for effort, euros a month for run cost." },
          { title: "Name the trade-offs", text: "For each option, write what choosing it gives up compared with the others. Make the run-cost trade-off visible, the dependency trade-off visible and the security trade-off visible. Use ISO/IEC 25010 terms where they help — “trades running cost for functional correctness” is clearer than “it’s pricier but better”.", tip: "If you can’t find anything an option gives up, you haven’t looked hard enough." },
          { title: "Write the recommendation", text: "One option. Why — in terms of the targets and the evidence. What it trades away. How reversible it is, and if it isn’t, why not. The conditions it depends on. Keep it short enough that the tech lead can read it in a minute and challenge it in five.", tip: "If the recommendation depends on a condition, make the recommendation itself conditional." },
          { title: "Decide: is the recommendation accepted?", text: "Take it to the tech lead. Before you do, have your agent argue against it as a sceptical tech lead would, so you can strengthen it or change it. If the comparison is incomplete, go back to step 1 and fill the gaps. If a trade-off affects the client’s targets, it goes to the client. If the tech lead prefers another option, record the disagreement and the reason — disagreements are recorded, not erased. If no option is acceptable, stop and record why in the learning log." },
        ] },
        { t: "figure", fig: { kind: "lanes", lanes: ["Engineer", "Agent", "Tech lead", "Client"], steps: [ { lane: 0, label: "Put options side by side", sub: "every cell sourced" }, { lane: 0, label: "Name the trade-offs" }, { lane: 0, label: "Write the recommendation", sub: "one option, why, reversibility, conditions" }, { lane: 1, label: "Argue against it", sub: "as a sceptical tech lead" }, { lane: 2, label: "Accept, or record the disagreement", flag: "ok" }, { lane: 3, label: "Trade-off on their targets", sub: "the client decides", flag: "wait" } ] }, caption: "Who does what. The agent’s challenge comes before the tech lead sees it, so the recommendation arrives already tested." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Here is Northwind’s comparison, row for row, pulled from the evaluation matrix, the feasibility assessment, the estimate and the register." },
        { t: "table", caption: "Northwind option comparison — TPS-01", head: ["Row", "Option A — managed document-AI", "Option B — self-hosted OCR + rules"], rows: [
          ["Quality targets", "Meets QA-1–3", "Misses QA-1 on scans"],
          ["Accuracy evidence", "Generated PDFs 96%, scans 88%", "Generated PDFs 93%, scans 71%"],
          ["Feasibility", "High — on condition of a signed DPA", "Medium — scan accuracy unresolved"],
          ["Effort", "16–40 days", "25–55 days"],
          ["Run cost", "~€550 a month", "~€150 a month"],
          ["Top risk", "Vendor cost at peak", "Scan accuracy"],
          ["Reversibility", "Extraction behind an adapter, so B can replace A later", "—"],
        ] },
        { t: "p", text: "The weighted scores from topic 1.4 point the same way. With the weights set first — line accuracy 40%, no lost orders 25%, peak latency 15%, EU data 20% — A scores 4, 4, 4 and 5, and B scores 3, 4, 5 and 5. Worked through, that is 4.2 for A against 3.95 for B. Close — closer than the comparison table suggests — which is exactly why the trade-offs and the scan result matter more than the total." },
        { t: "figure", fig: { kind: "scorecard", criteria: [ { label: "Line accuracy", weight: 40 }, { label: "No lost orders", weight: 25 }, { label: "Peak latency", weight: 15 }, { label: "EU data", weight: 20 } ], options: [ { label: "Option A — managed document-AI", scores: [4, 4, 4, 5] }, { label: "Option B — self-hosted OCR + rules", scores: [3, 4, 5, 5] } ], scale: 5, note: "Weights set before the scores were seen, in topic 1.4. Worked through: A 4.2, B 3.95." }, caption: "Northwind’s weighted scores. Try moving the weights: the totals stay close, which is why the trade-offs and the scan result decide, not the sum." },
        { t: "figure", fig: { kind: "split", left: { title: "Choosing A gives up", items: ["About €400 a month more in run cost than B", "Some vendor dependency", "Full control of the extraction step"], tone: "bad" }, right: { title: "Choosing A gets", items: ["The only option meeting QA-1 on scanned PDFs", "A smaller, faster build: 16–40 days", "An adapter that keeps B open as a later replacement"], tone: "good" } }, caption: "What recommending A trades, side by side. The run-cost gap is worked out from the comparison: about €550 against about €150 a month." },
        { t: "callout", tone: "case", title: "Northwind", text: "A is the only option meeting QA-1 on scans; it trades run cost for accuracy and sits behind an adapter so B can replace it later." },
        { t: "p", text: "Notice the three parts that make this recommendation strong. It names the reason in terms of a target (QA-1 on scans). It names the trade-off (run cost and some vendor dependency for accuracy and speed to build). And it designs in reversibility (the adapter). The condition — the vendor confirms EU processing and a DPA — comes straight from 1.5.1." },
        { t: "figure", fig: { kind: "hub", center: "What makes the recommendation strong", items: [ { label: "Reason tied to a target", icon: "flag", text: "QA-1 on scanned PDFs." }, { label: "Trade-off named", icon: "balance", text: "Run cost and some vendor dependency, for accuracy and speed to build." }, { label: "Reversibility designed in", icon: "swap_horiz", text: "Extraction behind an adapter, so B can replace A later." }, { label: "Condition carried from 1.5.1", icon: "rule", text: "The vendor confirms EU processing and a DPA." } ] }, caption: "The parts of Northwind’s recommendation. Take one away and the tech lead has something to overturn." },
        { t: "figure", fig: { kind: "flow", steps: [
          { label: "Inbox watcher", sub: "Microsoft 365, Graph API", tone: "new" },
          { label: "Queue", tone: "new" },
          { label: "Extraction adapter", sub: "document-AI, EU region — swappable", tone: "risk" },
          { label: "Validation & customer match", tone: "new" },
          { label: "ERP import API", sub: "C-01: the only way in", tone: "system" },
          { label: "Clerk review", sub: "low-confidence orders", tone: "human" },
        ] }, caption: "Option A, the recommendation. The adapter around extraction is what makes it reversible." },
        { t: "figure", fig: { kind: "template", id: "option-comparison" }, caption: "The option comparison and recommendation — side by side, trade-offs, recommendation, reversibility, conditions." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "The lesson suggests the agent for *challenging the recommendation*. You make the recommendation; the agent tries to knock it down. That way round, you get a stronger recommendation instead of a more confident one." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to write the strongest honest case for the option you’re *not* recommending. If your recommendation survives it, you’re ready." },
        { t: "prompt", title: "Build the comparison", text: "Using the option evaluation matrix, feasibility assessment, effort estimate and risk register below, build an option comparison. Draft and check; I decide.\n\n1. One column per option, including do nothing if it is still on the table.\n2. Fixed rows: quality targets met (by QA-##), feasibility rating, effort range, run cost, top risk, reversibility.\n3. Every cell cites its source artifact ID. Leave a cell marked GAP if the source doesn’t say — don’t fill it in.\n4. For each option, one sentence: what choosing it gives up compared with the others.\n\nDo not recommend yet.\n\nMaterial: [paste]" },
        { t: "p", text: "**What to check:** that every cell traces to an artifact; that GAPs are real gaps, not things the agent couldn’t be bothered to find; and that the losing options’ strengths are shown as fairly as the favourite’s." },
        { t: "prompt", title: "Argue against it", text: "Here is my recommendation and the comparison behind it. Argue against it as a sceptical tech lead would. Write the strongest honest case for the option I did NOT recommend, using only the evidence in the comparison. Then list the three questions I am most likely to be asked in review, and say which of them my recommendation does not yet answer.\n\nRecommendation and comparison: [paste]" },
        { t: "p", text: "**What to check:** whether the case for the losing option relies on evidence you’ve under-weighted. If it does, change the recommendation or say plainly why you still hold it." },
        { t: "figure", fig: { kind: "cycle", center: "Stronger, not more confident", steps: [ { label: "You recommend", text: "One option, why, what it trades, how reversible." }, { label: "Agent argues the other side", text: "The strongest honest case for the option you did not recommend, from the comparison only." }, { label: "Check the weighting", text: "Does that case rest on evidence you under-weighted?" }, { label: "Change or hold", text: "Change the recommendation, or say plainly why you still hold it." } ] }, caption: "You make the recommendation; the agent tries to knock it down. Repeat until it survives the case for the losing option." },

        { t: "h", text: "Common mistakes" },
        { t: "contrast", label: "A recommendation", bad: { title: "Advocacy", text: "“Option A is clearly the best choice. It uses a mature, modern cloud service and will be quick to build.”" }, good: { title: "A recommendation", text: "“Recommend A — the only option meeting QA-1 on scanned PDFs. It trades about €400 a month of extra run cost and some vendor dependency for accuracy and speed to build. Reversible: extraction sits behind an adapter so B can replace it. Conditional on the vendor confirming EU processing and a signed DPA.”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [ { text: "Recommend A", label: "Decision" }, { text: " — the only option meeting QA-1 on scanned PDFs.", label: "Reason" }, { text: " It trades about €400 a month of extra run cost and some vendor dependency for accuracy and speed to build.", label: "Trade-off" }, { text: " Reversible: extraction sits behind an adapter so B can replace it.", label: "Reversibility" }, { text: " Conditional on the vendor confirming EU processing and a signed DPA.", label: "Condition" } ] }, caption: "The good recommendation, taken apart. Advocacy has only the first part; a recommendation has all five." },
        { t: "pitfalls", items: [
          { trap: "Different rows for different options, so nothing is really compared.", fix: "Compare every option on the same rows." },
          { trap: "Leaving the trade-offs out to make the recommendation look cleaner.", fix: "Add a “what we give up” line." },
          { trap: "Showing the losing options unfairly — weaknesses only.", fix: "Show each option’s real strengths; let the evidence do the persuading." },
          { trap: "Recommending by habit — the stack you know or the newest one.", fix: "Tie every reason to a target, a rating, a range or a risk." },
          { trap: "Burying a condition the recommendation depends on.", fix: "Make the recommendation itself conditional, and say on what." },
          { trap: "Treating the weighted total as the verdict.", fix: "Use it as a summary; decide on the trade-offs and the critical targets." },
        ] },
        { t: "callout", tone: "warn", title: "Recommend, don’t advocate", text: "Show the losing options fairly. A recommendation that hides its trade-offs will be overturned the first time someone finds them." },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of the happy path", head: ["Situation", "What you do"], rows: [
          ["Comparison incomplete", "Rework: fill the gaps, then compare again"],
          ["Close call", "Recommend the cheaper-to-reverse option, with the reason"],
          ["Recommendation depends on a condition", "Make it conditional"],
          ["Only one option", "Compare it with doing nothing"],
          ["Tech lead prefers another option", "Record the disagreement and the reason"],
          ["Trade-off affects the client’s targets", "Escalate to the client — they decide trade-offs on their targets"],
          ["No option is acceptable", "Stop and record why — in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [ { id: "q1", q: "Is the comparison complete?", yes: "q2", no: "r1" }, { id: "r1", result: "Rework: fill the gaps, then compare again", tone: "bad" }, { id: "q2", q: "Is there only one option?", yes: "r2", no: "q3" }, { id: "r2", result: "Compare it with doing nothing", tone: "neutral" }, { id: "q3", q: "Is any option acceptable?", yes: "q4", no: "r3" }, { id: "r3", result: "Stop and record why — in the learning log", tone: "bad" }, { id: "q4", q: "Is it a close call?", yes: "r4", no: "q5" }, { id: "r4", result: "Recommend the cheaper-to-reverse option, with the reason", tone: "neutral" }, { id: "q5", q: "Does the recommendation depend on a condition?", yes: "r5", no: "q6" }, { id: "r5", result: "Make it conditional", tone: "neutral" }, { id: "q6", q: "Does a trade-off affect the client’s targets?", yes: "r6", no: "q7" }, { id: "r6", result: "Escalate to the client — they decide trade-offs on their targets", tone: "neutral" }, { id: "q7", q: "Does the tech lead prefer another option?", yes: "r7", no: "r8" }, { id: "r7", result: "Record the disagreement and the reason", tone: "neutral" }, { id: "r8", result: "Recommendation Accepted", tone: "good" } ] }, caption: "The routes out of the happy path as a walk-through. A disagreement is recorded, never erased." },
        { t: "figure", fig: { kind: "knowledge", name: "Decision record" }, caption: "The decision record: context, decision, options considered, consequences. The comparison you write here becomes its middle." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Every option compared on the same criteria", "Trade-offs stated in plain words", "The recommendation is reversible, or says why not", "Conditions carried from the feasibility assessment", "Links to ARO-##, EST-## and RSK-##"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Recommendation Accepted", items: [
          "Every option is on the same rows, every cell sourced",
          "Each option has a “what it gives up” line",
          "The recommendation names one option and why",
          "Reversibility is stated, or why not",
          "Conditions are carried into the recommendation",
          "The agent has argued the case for the losing option",
          "Trade-offs on the client’s targets have gone to the client",
          "The tech lead has accepted — or the disagreement is recorded",
        ] },
        { t: "try", text: "Write the “what we give up” line for recommending option A. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.5.4 ───────────────────────────── */
    {
      id: "discover.decide.record", fid: "discover.decide.record", code: "1.5.4", title: "Record the Decision (ADR) → Hand off to Plan", minutes: 11,
      blocks: [
        { t: "lead", text: "A decision that isn’t written down will be made again — usually by someone who doesn’t have your evidence. This last lesson commits to an approach explicitly, records it as an Architecture Decision Record, hands the evidence on to PLAN, and captures what discovery taught you." },
        { t: "tldr", items: [
          "Write the ADR: context, decision, options considered (each with why it lost), consequences good and bad, and dated conditions.",
          "Link every claim to its evidence by artifact ID.",
          "The tech lead accepts it in a decision review; anything beyond their authority goes to the client.",
          "Hand PLAN one pack: the ADR and everything it rests on.",
          "Log what discovery taught you. And record every outcome — including “do not build”.",
        ] },
        { t: "p", text: "The job: *help me record what we decided and why, so nobody has to rediscover it.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Decisions made in meetings and chats evaporate. Six months later someone asks “why didn’t we just self-host the OCR?”, and either nobody remembers, or somebody remembers wrongly, or the team spends a week rediscovering the answer. The concerns the lesson names are exactly these: **decisions lost in chat**, and **rediscovering the same answers later**." },
        { t: "p", text: "An ADR is the cure. It is short — a page or two — and it captures not only what you chose but why, what else you considered, and what it will cost. It is also the hinge between Act I and Act II: PLAN starts from the ADR and its handoff pack, not from a conversation." },
        { t: "figure", fig: { kind: "split", left: { title: "Decided in chat", items: ["Nobody remembers", "Somebody remembers wrongly", "A week spent rediscovering the answer"], tone: "bad" }, right: { title: "Recorded in an ADR", items: ["What you chose", "Why", "What else you considered", "What it will cost"], tone: "good" } }, caption: "Six months later, someone asks why. On the left the answer has evaporated; on the right it is a page or two away." },
        { t: "pull", text: "A decision that isn’t written down will be made again." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start from the **option comparison & recommendation** (1.5.3) and the artifacts it rests on: the **feasibility assessment**, the **risk register** and the **effort estimate**. The entry condition is that the recommendation was accepted. You produce three things: the **technical decision record (ADR)**, the **technical discovery handoff pack** for PLAN, and entries in the **learning log** for EVOLVE." },
        { t: "table", caption: "Inputs, outputs and people", head: ["", "What"], rows: [
          ["Comes in", "Option comparison & recommendation, feasibility assessment, risk register, effort estimate"],
          ["Goes out", "ADR (ADR-###), technical discovery handoff pack, learning log (LRN-###)"],
          ["Accountable", "Tech lead — owns the decision"],
          ["Responsible", "Engineer — writes the ADR, links evidence, assembles the pack, logs the learning"],
          ["Consulted", "Architect"],
          ["Informed", "Client contact, PLAN team"],
          ["Tools", "ADR log, document repository"],
          ["Timebox", "2–4 hours; learning captured while the pack is assembled"],
          ["Gate", "Technical Discovery Decision — the gate for Act I"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Record the decision", sub: "1.5.4" }, around: [ { label: "Option comparison & recommendation", sub: "1.5.3", type: "store", dir: "in" }, { label: "Feasibility, risks, estimate", sub: "the evidence it rests on", type: "store", dir: "in" }, { label: "Engineer", sub: "Responsible", type: "person", link: "writes, links, assembles, logs" }, { label: "Tech lead", sub: "Accountable", type: "person", link: "owns the decision" }, { label: "Architect", sub: "Consulted", type: "person" }, { label: "Client contact", sub: "Informed", type: "person", dir: "out" }, { label: "PLAN team", sub: "Informed", type: "person", link: "handoff pack", dir: "out" }, { label: "ADR log", sub: "ADR-###", type: "store", dir: "out" }, { label: "Learning log", sub: "LRN-### · for EVOLVE", type: "store", dir: "out" } ] }, caption: "The hinge of the act: the accepted recommendation and its evidence come in; the ADR, the handoff pack for PLAN and the learning log go out." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "What an ADR is" },
        { t: "p", text: "An Architecture Decision Record is a short document that captures one significant decision. The format was popularised by Michael Nygard, and arc42 gives architecture decisions their own section. ISO/IEC/IEEE 42010, the standard for architecture descriptions, likewise expects the rationale for decisions to be recorded. The common core is four parts: **context** (the problem and the forces at play), **decision** (what we will do, in a sentence or two), **options considered** (each with why it lost) and **consequences** (good and bad). This program adds **conditions & evidence**: dated conditions, and links to the spikes, estimates and risks." },
        { t: "figure", fig: { kind: "tree", root: "An ADR", children: [ { label: "The common core", children: [ { label: "Context", text: "The problem and the forces at play." }, { label: "Decision", text: "What we will do, in a sentence or two." }, { label: "Options considered", text: "Each with why it lost." }, { label: "Consequences", text: "Good and bad." } ] }, { label: "Added by this program", children: [ { label: "Conditions", text: "Dated." }, { label: "Evidence", text: "Links to the spikes, estimates and risks." } ] } ] }, caption: "The four parts every ADR format shares, and the two this program adds so the record can be checked." },
        { t: "figure", fig: { kind: "knowledge", name: "arc42" }, caption: "arc42 gives architecture decisions their own place in the architecture documentation — the ADR is how you fill it." },
        { t: "h3", text: "Status and versions" },
        { t: "p", text: "An ADR has a status: **proposed**, **accepted** or **superseded**. The policy is that ADRs are versioned, never edited silently. If the decision changes later, you write a new ADR that supersedes the old one; the old one stays, so the history of why is never lost. Keep them in an ADR log — a numbered list, usually beside the code." },
        { t: "figure", fig: { kind: "flow", steps: [ { label: "Proposed", sub: "written, not yet accepted" }, { label: "Accepted", sub: "in the decision review" }, { label: "Superseded", sub: "by a new ADR; the old one stays" } ] }, caption: "An ADR’s status over its life. A changed decision never edits the old record; a new ADR supersedes it, so the history of why is kept." },
        { t: "h3", text: "“Do not build” is a result" },
        { t: "p", text: "The rule here is that **every outcome is recorded — including “do not build”.** If discovery shows that nothing is feasible, or nothing is acceptable, the ADR says so and says why. That ADR is a success: it saved the cost of finding out the hard way, and it saves the next team from rediscovering it." },
        { t: "h3", text: "The handoff and the learning" },
        { t: "p", text: "PLAN doesn’t need your notes; it needs the pack. One paragraph per part with links: the ADR, the problem statement, the options, the estimates, the risks, the system context and the success metrics. Separately, a short retrospective of discovery itself goes into the learning log: what surprised you, what you’d do differently, and the change you’ll make next time — each with an owner." },
        { t: "figure", fig: { kind: "hub", center: "Technical discovery handoff pack", items: [ { label: "ADR", icon: "gavel", text: "What we decided, and why." }, { label: "Problem statement", icon: "report", text: "The problem, measured." }, { label: "Options", icon: "compare_arrows", text: "What was considered." }, { label: "Estimates", icon: "timer", text: "How big." }, { label: "Risks", icon: "warning", text: "What could go wrong." }, { label: "System context", icon: "hub", text: "The system today." }, { label: "Success metrics", icon: "insights", text: "How success is measured." } ] }, caption: "What PLAN starts from: one paragraph per part, each with its link. PLAN doesn’t need your notes; it needs the pack." },
        { t: "terms", items: [
          { term: "ADR", def: "Architecture Decision Record: context, decision, options considered, consequences — plus, here, dated conditions and linked evidence." },
          { term: "Status", def: "Proposed, accepted or superseded. A changed decision gets a new ADR; the old one is kept." },
          { term: "Decision review", def: "The meeting where the tech lead accepts the ADR, challenges it, or sends it on to the client." },
          { term: "Handoff pack", def: "The ADR and everything it rests on, one paragraph per part, with links — what PLAN starts from." },
          { term: "Learning log", def: "Numbered entries (LRN-###) of what happened, what was learned and the change to make — each with an owner." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "figure", fig: { kind: "workflow", fid: "discover.decide.record" }, caption: "Record the Decision — write, link, accept, hand off, learn." },
        { t: "steps", items: [
          { title: "Write the ADR", text: "Start from the accepted recommendation. Give the ADR a number and a title that states the decision. Write the context from the technical problem statement and the forces — the constraints, the targets. Write the decision in one or two sentences. List every option considered, each with why it lost — including do nothing. Write the consequences, good and bad, and the conditions with dates. Mark the status as proposed.", tip: "Write the title as the decision itself, not the topic: “Extract orders with a managed document-AI service”, not “Extraction approach”." },
          { title: "Link the evidence", text: "Go through the ADR claim by claim and attach the artifact ID that supports it: the spike, the estimate, the risk, the baseline. Then list anything unlinked. Every unlinked claim is either removed, softened to what you can show, or sent back for evidence — back to 1.4 if it needs more research.", tip: "Ask: could someone who wasn’t in the room check every sentence of this ADR from the links alone?" },
          { title: "Decide: is the decision accepted?", text: "Hold the decision review. Prepare the ADR summary and the questions the tech lead is likely to ask. The tech lead accepts the decision with its conditions dated, and any security conditions carried in the ADR. Evidence gaps go back to be linked or gathered. A decision beyond the tech lead’s authority goes to the client. If the tech lead overrules the recommendation, the ADR records both. If the outcome is “not feasible”, the ADR says so — and you go straight to capturing the learning." },
          { title: "Assemble the handoff pack", text: "Build the technical discovery handoff pack for PLAN: one paragraph per part — ADR, problem statement, options, estimates, risks, system context, success metrics — each with its link. Include the run and support needs, so PLAN doesn’t plan a build and forget the operation. The exit is the pack received by PLAN, not merely sent.", tip: "Walk a member of the PLAN team through it for ten minutes. Their questions show you what the pack is missing." },
          { title: "Capture what discovery taught you", text: "Write learning-log entries from this discovery: what surprised you, what you’d do differently, and the change you’ll make next time — each with an owner. Include the things that later need checking: estimates against actuals, unknowns that became problems, recommendations later reversed. This is what EVOLVE uses, and what makes the next discovery better." },
        ] },
        { t: "figure", fig: { kind: "lanes", lanes: ["Engineer", "Tech lead", "Client", "PLAN team"], steps: [ { lane: 0, label: "Write the ADR", sub: "status: proposed" }, { lane: 0, label: "Link the evidence", sub: "claim by claim" }, { lane: 1, label: "Decision review", sub: "accepts with conditions dated", flag: "ok" }, { lane: 2, label: "Beyond the tech lead’s authority", sub: "escalated", flag: "wait" }, { lane: 0, label: "Assemble the handoff pack", sub: "with run and support needs" }, { lane: 3, label: "Receive the pack", sub: "the exit", flag: "ok" }, { lane: 0, label: "Capture the learning", sub: "each entry with an owner" } ] }, caption: "Who does what. Note the two exits that need someone else: the tech lead’s acceptance, and PLAN actually receiving the pack." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s ADR is short, and every line can be traced. Here it is, section by section." },
        { t: "table", caption: "ADR-001 — Extract orders with a managed document-AI service", head: ["Section", "What it says"], rows: [
          ["Context", "TPS-01: orders re-keyed by hand, 13 min and 3.1% wrong lines; C-01 import API only; C-02 EU data."],
          ["Decision", "Build an order-intake service that extracts PDF orders with a managed document-AI service (EU region) behind an adapter, and creates orders through the ERP import API; low-confidence orders go to a clerk review screen."],
          ["Options considered", "B self-hosted OCR — failed QA-1 on scans (71%). Vendor X connector — no confirmed support for ERP v9. Do nothing — 13 min an order at double peak volume."],
          ["Consequences", "+ meets QA-1–3, ~16–40 days. − ~€550/month run cost; vendor dependency (mitigated by the adapter)."],
          ["Conditions & evidence", "DPA signed by 30 May · SPK-1, SPK-2, EST-A, RSK-01–04."],
          ["Status", "Accepted, with the DPA as a dated condition. Signed off by the tech lead."],
        ] },
        { t: "callout", tone: "case", title: "Northwind", text: "ADR-001 is accepted with the DPA as a dated condition. The handoff pack goes to PLAN; LRN-007 notes: check vendor ERP support in the first scan." },
        { t: "p", text: "Look at the options considered. Every option from the technology scan appears — including the Vendor X connector, which never made the shortlist because Vendor X couldn’t confirm ERP v9 support, and do nothing. Each has a reason it lost, in evidence terms. Someone reading this in a year can see that self-hosting was considered, why it lost, and that the adapter leaves the door open." },
        { t: "figure", fig: { kind: "tree", root: "ADR-001: options considered", children: [ { label: "Managed document-AI", text: "Chosen: meets QA-1–3, behind an adapter." }, { label: "B — self-hosted OCR", text: "Failed QA-1 on scans (71%)." }, { label: "Vendor X connector", text: "No confirmed support for ERP v9." }, { label: "Do nothing", text: "13 min an order at double peak volume." } ] }, caption: "Every option from the technology scan, each with the reason it lost in evidence terms — so nobody has to rediscover them in a year." },
        { t: "figure", fig: { kind: "template", id: "discovery-adr" }, caption: "The technical decision record (ADR) — context, decision, options considered, consequences, conditions & evidence." },
        { t: "p", text: "The handoff pack for REQ-014 bundles the ADR with everything it rests on, so PLAN starts from evidence:" },
        { t: "figure", fig: { kind: "template", id: "technical-handoff" }, caption: "The technical discovery handoff pack — what we decided, the problem measured, the options, how big, what could go wrong, the system today, and how success is measured." },
        { t: "p", text: "And the learning. LRN-007 records that the vendor dependency surfaced late — in 1.5 — when it should have been scanned in 1.4. The change: add a vendor-support check to the existing-solutions scan. Type: retrospective. Owner: the product manager." },
        { t: "figure", fig: { kind: "anatomy", parts: [ { text: "LRN-007:", label: "Entry" }, { text: " the vendor dependency surfaced late — in 1.5 —", label: "What happened" }, { text: " when it should have been scanned in 1.4.", label: "What we learned" }, { text: " Change: add a vendor-support check to the existing-solutions scan.", label: "The change" }, { text: " Type: retrospective.", label: "Type" }, { text: " Owner: the product manager.", label: "Owner" } ] }, caption: "A learning-log entry, taken apart. A learning names a concrete change and an owner, not a feeling." },
        { t: "figure", fig: { kind: "template", id: "learning-log" }, caption: "The learning log — what happened, what we learned, the change we’ll make, and who owns it." },
        { t: "figure", fig: { kind: "trace" }, caption: "The full chain the ADR rests on — from the first request to the decision and what you learned." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Agents are good at the shape of an ADR and at spotting unlinked claims. They are also capable of writing a confident decision record that quietly drops the options you rejected, or describes them unfairly. You own the decision; the agent drafts and checks the record of it." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Give your agent the comparison, feasibility, estimate and risk register and ask for an ADR in the standard shape with every claim linked to its artifact ID. Check the conditions are dated and that the options you rejected are described fairly." },
        { t: "prompt", title: "Draft and link the ADR", text: "Write ADR-001 from my accepted recommendation and the artifacts below. Draft and check; I decide.\n\nSections: title (stating the decision), status (Proposed), context, decision (one or two sentences), options considered (each with why it lost, including do nothing), consequences (good and bad), conditions (each with a date and an owner) and evidence.\n\nThen go through it claim by claim and attach the artifact ID that supports each one — spike, estimate, risk, baseline. List every claim you could NOT link, separately, at the end.\n\nDon’t add any claim that isn’t in my material.\n\nRecommendation, comparison, feasibility assessment, effort estimate, risk register: [paste]" },
        { t: "p", text: "**What to check:** every rejected option appears and is described fairly; every condition has a date; the unlinked list is short, and you deal with every item on it; nothing new has crept in that isn’t in your evidence." },
        { t: "prompt", title: "Prepare the review and the learning", text: "1. Prepare a decision review for the tech lead: a five-line summary of ADR-001 and the six questions they are most likely to ask, each with where in the evidence the answer is.\n2. Then draft learning-log entries from this discovery: what surprised us, what we would do differently, and the change we will make next time. Leave the owner blank for me.\n\nADR and discovery artifacts: [paste]" },
        { t: "p", text: "**What to check:** that the questions are the hard ones, not the easy ones; that each learning names a concrete change, not a feeling; and that you, not the agent, assign the owners." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [ { lane: 0, label: "Give the accepted recommendation", sub: "and the artifacts" }, { lane: 1, label: "Draft ADR-001", sub: "standard sections, status Proposed" }, { lane: 1, label: "Link claim by claim", sub: "unlinked claims listed at the end" }, { lane: 0, label: "Check the draft", sub: "rejected options fair, conditions dated, unlinked items dealt with" }, { lane: 1, label: "Prepare the decision review", sub: "five-line summary, six likely questions" }, { lane: 2, label: "Decision review", flag: "ok" }, { lane: 1, label: "Draft learning entries", sub: "owner left blank" }, { lane: 0, label: "Assign the owners" } ] }, caption: "You own the decision; the agent drafts and checks the record of it. Every owner and every final call stays with a person." },

        { t: "h", text: "Common mistakes" },
        { t: "contrast", label: "Options considered", bad: { title: "Missing", text: "“We considered alternatives and chose document-AI as the best fit.”" }, good: { title: "Each with why it lost", text: "“B self-hosted OCR — failed QA-1 on scans (71%). Vendor X connector — no confirmed support for ERP v9. Do nothing — 13 min an order at double peak volume.”" } },
        { t: "contrast", label: "A learning", bad: { title: "A feeling", text: "“We should be more careful with vendors next time.”" }, good: { title: "A change with an owner", text: "“Vendor dependency surfaced late (1.5) — should be scanned in 1.4. Change: add a vendor-support check to the existing-solutions scan. Owner: product manager.”" } },
        { t: "pitfalls", items: [
          { trap: "The decision lives only in chat or a meeting.", fix: "Write it up from the meeting the same day." },
          { trap: "An ADR without the options considered.", fix: "Add the losing options and why they lost." },
          { trap: "Conditions without dates.", fix: "Date every condition and name who checks it." },
          { trap: "Editing an accepted ADR when the decision changes.", fix: "Write a new ADR that supersedes it. ADRs are versioned, never edited silently." },
          { trap: "Skipping the ADR because the answer was “no”.", fix: "Record “do not build” and why. It saves the next team from rediscovering it." },
          { trap: "Sending the pack and calling it done.", fix: "The exit is the pack *received* by PLAN — walk them through it." },
        ] },
        { t: "callout", tone: "key", title: "Every outcome is recorded", text: "Including “do not build”. An ADR that says “not feasible, and here is why” is a successful discovery: it saved the cost of finding out the hard way." },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of the happy path", head: ["Situation", "What you do"], rows: [
          ["Evidence gaps", "Rework: link or gather — back to 1.4 if new research is needed"],
          ["Decision is conditional", "Conditions and a date in the ADR"],
          ["Decision beyond the tech lead’s authority", "Escalate to the client"],
          ["Tech lead overrules the recommendation", "The ADR records both"],
          ["Small change", "A short ADR — same sections"],
          ["Not feasible", "The ADR records “do not build” and why; learning logged"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [ { id: "q1", q: "Are there evidence gaps?", yes: "r1", no: "q2" }, { id: "r1", result: "Rework: link or gather — back to 1.4 if new research is needed", tone: "bad" }, { id: "q2", q: "Is the outcome “not feasible”?", yes: "r2", no: "q3" }, { id: "r2", result: "The ADR records “do not build” and why; learning logged", tone: "neutral" }, { id: "q3", q: "Is the decision beyond the tech lead’s authority?", yes: "r3", no: "q4" }, { id: "r3", result: "Escalate to the client", tone: "neutral" }, { id: "q4", q: "Does the tech lead overrule the recommendation?", yes: "r4", no: "q5" }, { id: "r4", result: "The ADR records both", tone: "neutral" }, { id: "q5", q: "Is the decision conditional?", yes: "r5", no: "q6" }, { id: "r5", result: "Conditions and a date in the ADR", tone: "neutral" }, { id: "q6", q: "Is it a small change?", yes: "r6", no: "r7" }, { id: "r6", result: "A short ADR — same sections", tone: "good" }, { id: "r7", result: "The full ADR, accepted by the tech lead", tone: "good" } ] }, caption: "The routes out of the happy path as a walk-through. Every route ends in a record — including “do not build”." },
        { t: "note", text: "The measures to watch later are days from options to decision, and decisions reversed later. A reversed decision isn’t a disgrace if the ADR shows why it was made — that is what makes the reversal cheap." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Context, decision, options and consequences all present", "Evidence linked by ID", "Conditions dated", "The handoff pack is with PLAN and the learning is logged"] },
        { t: "h", text: "Before you move on — the gate for Act I" },
        { t: "checklist", title: "Technical Discovery Decision", items: [
          "Feasibility evidenced — every rating cites a spike or document",
          "Estimates as ranges — low / likely / high, each with a basis",
          "Risks owned — every risk has a named owner and a mitigation",
          "Trade-offs stated — what the choice gives up, in plain words",
          "ADR complete — context, decision, options considered, consequences",
          "Every claim in the ADR links to its evidence",
          "Every condition has a date",
          "The ADR is accepted by the tech lead",
          "The handoff pack has been received by PLAN",
          "What discovery taught us is in the learning log, each entry with an owner",
        ] },
        { t: "try", text: "Write ADR-001 for the order-intake case. Then do the same for your own project." },
      ],
    },
  ],
};
